class Solution { fun rangeAddQueries(n:Int,queries:Array<IntArray>):Array<IntArray>{val difference=Array(n+1){IntArray(n+1)};for(query in queries){val r1=query[0];val c1=query[1];val r2=query[2];val c2=query[3];difference[r1][c1]++;difference[r2+1][c1]--;difference[r1][c2+1]--;difference[r2+1][c2+1]++};val answer=Array(n){IntArray(n)};for(row in 0 until n)for(col in 0 until n)answer[row][col]=difference[row][col]+(if(row>0)answer[row-1][col]else 0)+(if(col>0)answer[row][col-1]else 0)-(if(row>0&&col>0)answer[row-1][col-1]else 0);return answer} }
